"use client";

// New: the backend requires an account. This form covers both signup and
// login (toggle between them) and surfaces the backend's error message
// directly — e.g. "Please provide a valid email address." or "Incorrect
// email or password." — rather than a generic failure string.

import { useState } from "react";
import { useAuth } from "@/lib/auth-context";
import { ApiError } from "@/lib/codesage-client";

export default function AuthForm() {
  const { login, signup } = useAuth();
  const [mode, setMode] = useState<"login" | "signup">("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      if (mode === "login") {
        await login(email, password);
      } else {
        await signup(email, password);
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Something went wrong. Try again.");
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="mx-auto max-w-sm">
      <div className="flex gap-1 rounded-sm border border-line p-1">
        <button
          type="button"
          onClick={() => setMode("login")}
          className={`focus-ring flex-1 rounded-sm px-3 py-2 text-sm font-medium transition-colors ${
            mode === "login" ? "bg-add text-ink" : "text-muted hover:text-fg"
          }`}
        >
          Log in
        </button>
        <button
          type="button"
          onClick={() => setMode("signup")}
          className={`focus-ring flex-1 rounded-sm px-3 py-2 text-sm font-medium transition-colors ${
            mode === "signup" ? "bg-add text-ink" : "text-muted hover:text-fg"
          }`}
        >
          Sign up
        </button>
      </div>

      <form onSubmit={handleSubmit} className="mt-6 flex flex-col gap-4">
        <label className="flex flex-col gap-1.5">
          <span className="font-mono text-xs text-muted">Email</span>
          <input
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            className="focus-ring rounded-sm border border-line bg-surface px-4 py-3 font-mono text-sm text-fg placeholder:text-muted"
          />
        </label>

        <label className="flex flex-col gap-1.5">
          <span className="font-mono text-xs text-muted">Password</span>
          <input
            type="password"
            required
            minLength={mode === "signup" ? 8 : undefined}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder={mode === "signup" ? "At least 8 characters" : "••••••••"}
            className="focus-ring rounded-sm border border-line bg-surface px-4 py-3 font-mono text-sm text-fg placeholder:text-muted"
          />
        </label>

        {error && (
          <p className="rounded-sm border border-remove/40 bg-remove/10 px-3 py-2 font-mono text-[13px] text-remove">
            {error}
          </p>
        )}

        <button
          type="submit"
          disabled={submitting || !email.trim() || !password}
          className="focus-ring rounded-sm bg-add px-6 py-3 text-sm font-medium text-ink transition-opacity hover:opacity-90 disabled:opacity-40"
        >
          {submitting
            ? mode === "login"
              ? "Logging in..."
              : "Creating account..."
            : mode === "login"
              ? "Log in"
              : "Create account"}
        </button>
      </form>
    </div>
  );
}
