// The backend now returns citations as plain strings, e.g.
// "app/main.py:212-233 (ingest)" — there's no structured file/line/url
// object anymore, and no guaranteed github url (a repo can be ingested
// from a local path). So this just renders the string as a styled chip
// instead of a link.

export default function CitationLink({ citation }: { citation: string }) {
  return (
    <span className="inline-block rounded-sm bg-addDim px-1.5 py-0.5 font-mono text-[13px] text-add">
      {citation}
    </span>
  );
}
