"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import RepoInput from "@/components/RepoInput";
import RepoList from "@/components/RepoList";
import HistoryPanel from "@/components/HistoryPanel";
import ChatMessage, { Message } from "@/components/ChatMessage";
import AuthForm from "@/components/AuthForm";
import { useAuth } from "@/lib/auth-context";
import {
  startIngest,
  pollIngest,
  queryRepo,
  listRepos,
  deleteRepo,
  getHistory,
  ApiError,
  type RepoSummary,
  type HistoryEntry,
} from "@/lib/codesage-client";

type Status = "idle" | "ingesting" | "ready" | "querying" | "error";
type Tab = "chat" | "history";

export default function DemoPage() {
  const { token, email, status: authStatus, logout } = useAuth();

  const [status, setStatus] = useState<Status>("idle");
  const [messages, setMessages] = useState<Message[]>([]);
  const [question, setQuestion] = useState("");

  const [repos, setRepos] = useState<RepoSummary[]>([]);
  const [reposLoading, setReposLoading] = useState(false);
  const [activeRepo, setActiveRepo] = useState<string | null>(null);

  const [tab, setTab] = useState<Tab>("chat");
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  // Load the user's repos once they're logged in.
  useEffect(() => {
    if (!token) return;
    refreshRepos();
  }, [token]);

  async function refreshRepos() {
    if (!token) return;
    setReposLoading(true);
    try {
      setRepos(await listRepos(token));
    } catch {
      // Non-fatal — the repo list is a convenience panel, not required to
      // ask a question against a repo you already know the name of.
    } finally {
      setReposLoading(false);
    }
  }

  async function refreshHistory() {
    if (!token) return;
    setHistoryLoading(true);
    try {
      setHistory(await getHistory(token));
    } catch {
      // same as above — non-fatal
    } finally {
      setHistoryLoading(false);
    }
  }

  function openHistoryTab() {
    setTab("history");
    refreshHistory();
  }

  async function handleRepoSubmit(source: string, repoName?: string) {
    if (!token) return;
    setStatus("ingesting");
    setMessages([{ role: "system", content: `Queuing ${source} for ingestion...` }]);

    try {
      const { jobId } = await startIngest(token, source, repoName);
      const finalStatus = await pollIngest(token, jobId, {
        onUpdate: (s) => {
          setMessages((m) => [
            ...m.slice(0, 1),
            {
              role: "system",
              content:
                s.status === "running"
                  ? `Ingesting ${source}... (cloning, chunking, embedding — this can take a few minutes)`
                  : `Queued (${s.status})...`,
            },
          ]);
        },
      });

      const result = finalStatus.result;
      setActiveRepo(result?.repo ?? repoName ?? source);
      setStatus("ready");
      setMessages((m) => [
        ...m,
        {
          role: "system",
          content: result
            ? `Ready — indexed ${result.chunks_indexed} chunks from ${result.files_seen} files in ${result.repo}. Ask a question about it.`
            : "Ready. Ask a question about this repo.",
        },
      ]);
      refreshRepos();
    } catch (err) {
      setStatus("error");
      setMessages((m) => [
        ...m,
        {
          role: "system",
          content:
            err instanceof ApiError
              ? `Ingestion failed: ${err.message}`
              : err instanceof Error
                ? err.message
                : "Couldn't reach the backend. Check NEXT_PUBLIC_CODESAGE_API_URL is set and the API is running.",
        },
      ]);
    }
  }

  async function handleAsk(e: React.FormEvent) {
    e.preventDefault();
    if (!question.trim() || !token) return;
    const q = question.trim();
    setQuestion("");
    setMessages((m) => [...m, { role: "user", content: q }]);
    setStatus("querying");
    try {
      const result = await queryRepo(token, q, activeRepo);
      setMessages((m) => [
        ...m,
        { role: "assistant", content: result.answer, citations: result.citations },
      ]);
      setStatus("ready");
    } catch (err) {
      setMessages((m) => [
        ...m,
        {
          role: "system",
          content:
            err instanceof ApiError
              ? `That query failed: ${err.message}`
              : "That query failed. Try again in a moment.",
        },
      ]);
      setStatus("ready");
    }
  }

  async function handleDeleteRepo(repo: string) {
    if (!token) return;
    try {
      await deleteRepo(token, repo);
      if (activeRepo === repo) setActiveRepo(null);
      refreshRepos();
    } catch (err) {
      setMessages((m) => [
        ...m,
        {
          role: "system",
          content:
            err instanceof ApiError
              ? `Couldn't delete ${repo}: ${err.message}`
              : `Couldn't delete ${repo}.`,
        },
      ]);
    }
  }

  const canAskDirectly = repos.length > 0; // at least one repo already indexed this session or before

  return (
    <main className="min-h-screen">
      <header className="border-b border-line">
        <div className="mx-auto flex max-w-5xl items-center justify-between px-6 py-5">
          <Link href="/" className="font-display text-lg font-medium text-fg">
            codebase12
          </Link>
          <div className="flex items-center gap-4">
            <span className="font-mono text-xs text-muted">demo</span>
            {authStatus === "authed" && (
              <>
                <span className="font-mono text-xs text-muted">{email}</span>
                <button
                  type="button"
                  onClick={logout}
                  className="focus-ring rounded-sm border border-line px-3 py-1.5 text-xs text-fg hover:border-add hover:text-add"
                >
                  Log out
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      {authStatus === "loading" && (
        <div className="mx-auto max-w-3xl px-6 py-20 text-center font-mono text-sm text-muted">
          Loading...
        </div>
      )}

      {authStatus === "anon" && (
        <div className="mx-auto max-w-3xl px-6 py-16">
          <h1 className="font-display text-2xl font-medium text-fg">
            Log in to ask a repo something
          </h1>
          <p className="mt-2 text-[15px] text-muted">
            Every indexed repo, question, and answer is scoped to your
            account.
          </p>
          <div className="mt-10">
            <AuthForm />
          </div>
        </div>
      )}

      {authStatus === "authed" && (
        <div className="mx-auto max-w-5xl px-6 py-12">
          <div className="grid gap-10 md:grid-cols-[minmax(0,1fr)_260px]">
            <div>
              <h1 className="font-display text-2xl font-medium text-fg">
                Ask a repo something
              </h1>
              <p className="mt-2 text-[15px] text-muted">
                Paste a GitHub repo URL (or a local path, if you're running
                the backend yourself) to index it, then ask questions.
              </p>

              <div className="mt-8">
                <RepoInput
                  onSubmit={handleRepoSubmit}
                  disabled={status === "ingesting" || status === "querying"}
                />
              </div>

              <div className="mt-8 flex gap-1 border-b border-line">
                <button
                  type="button"
                  onClick={() => setTab("chat")}
                  className={`focus-ring px-3 py-2 font-mono text-xs ${
                    tab === "chat" ? "border-b-2 border-add text-add" : "text-muted hover:text-fg"
                  }`}
                >
                  Chat
                </button>
                <button
                  type="button"
                  onClick={openHistoryTab}
                  className={`focus-ring px-3 py-2 font-mono text-xs ${
                    tab === "history" ? "border-b-2 border-add text-add" : "text-muted hover:text-fg"
                  }`}
                >
                  History
                </button>
              </div>

              {tab === "chat" ? (
                <>
                  {messages.length > 0 && (
                    <div className="mt-8 space-y-6 pt-2">
                      {messages.map((m, i) => (
                        <ChatMessage key={i} message={m} />
                      ))}
                    </div>
                  )}

                  {(status === "ready" || status === "querying") && canAskDirectly && (
                    <form onSubmit={handleAsk} className="mt-8 flex gap-3">
                      <input
                        type="text"
                        value={question}
                        onChange={(e) => setQuestion(e.target.value)}
                        placeholder={
                          activeRepo
                            ? `Ask about ${activeRepo}...`
                            : "Where's auth handled?"
                        }
                        disabled={status === "querying"}
                        className="focus-ring flex-1 rounded-sm border border-line bg-surface px-4 py-3 font-mono text-sm text-fg placeholder:text-muted"
                      />
                      <button
                        type="submit"
                        disabled={!question.trim() || status === "querying"}
                        className="focus-ring rounded-sm bg-add px-6 py-3 text-sm font-medium text-ink transition-opacity hover:opacity-90 disabled:opacity-40"
                      >
                        {status === "querying" ? "Asking..." : "Ask"}
                      </button>
                    </form>
                  )}

                  {!canAskDirectly && status !== "ingesting" && messages.length === 0 && (
                    <p className="mt-8 font-mono text-xs text-muted">
                      No repos indexed yet — load one above, or pick one from
                      the panel if you've already indexed some.
                    </p>
                  )}
                </>
              ) : (
                <div className="mt-8 pt-2">
                  <HistoryPanel entries={history} loading={historyLoading} />
                </div>
              )}
            </div>

            <aside>
              <h2 className="font-mono text-xs uppercase tracking-wide text-muted">
                Your repos
              </h2>
              <div className="mt-3">
                <RepoList
                  repos={repos}
                  activeRepo={activeRepo}
                  onSelect={(r) => {
                    setActiveRepo(r);
                    if (r) setStatus("ready");
                  }}
                  onDelete={handleDeleteRepo}
                  loading={reposLoading}
                />
              </div>
            </aside>
          </div>
        </div>
      )}
    </main>
  );
}
