"use client";

// New: GET /history didn't exist before — each user's own past
// questions/answers, retrievable across sessions/devices.

import type { HistoryEntry } from "@/lib/codesage-client";
import CitationLink from "./CitationLink";

export default function HistoryPanel({
  entries,
  loading,
}: {
  entries: HistoryEntry[];
  loading?: boolean;
}) {
  if (loading) {
    return <p className="font-mono text-xs text-muted">Loading history...</p>;
  }

  if (entries.length === 0) {
    return (
      <p className="font-mono text-xs text-muted">
        Nothing asked yet. Your past questions will show up here.
      </p>
    );
  }

  return (
    <div className="flex flex-col gap-5">
      {entries.map((h) => (
        <div key={h.id} className="border-b border-line pb-5 last:border-0">
          <p className="font-mono text-[13px] text-fg">
            <span className="text-add">{"> "}</span>
            {h.question}
          </p>
          {h.repoFilter && (
            <p className="mt-1 font-mono text-[11px] text-muted">
              scoped to {h.repoFilter}
            </p>
          )}
          <p className="mt-2 text-[14px] leading-relaxed text-muted">
            {h.answer}
          </p>
          {h.citations.length > 0 && (
            <div className="mt-2 flex flex-wrap gap-2">
              {h.citations.map((c, i) => (
                <CitationLink key={i} citation={c} />
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}
