"use client";

// New: GET /repos and DELETE /repos/{repo_name} didn't exist before.
// Shows every repo the logged-in user has indexed, with a chunk count,
// a delete button, and a click-to-select for scoping queries via
// repo_filter.

import type { RepoSummary } from "@/lib/codesage-client";

export default function RepoList({
  repos,
  activeRepo,
  onSelect,
  onDelete,
  loading,
}: {
  repos: RepoSummary[];
  activeRepo: string | null;
  onSelect: (repo: string | null) => void;
  onDelete: (repo: string) => void;
  loading?: boolean;
}) {
  if (loading) {
    return <p className="font-mono text-xs text-muted">Loading your repos...</p>;
  }

  if (repos.length === 0) {
    return (
      <p className="font-mono text-xs text-muted">
        No repos indexed yet — load one above to get started.
      </p>
    );
  }

  return (
    <div className="flex flex-col gap-2">
      <button
        type="button"
        onClick={() => onSelect(null)}
        className={`focus-ring rounded-sm border px-3 py-2 text-left font-mono text-xs transition-colors ${
          activeRepo === null
            ? "border-add text-add"
            : "border-line text-muted hover:text-fg"
        }`}
      >
        All repos (no filter)
      </button>

      {repos.map((r) => (
        <div
          key={r.repo}
          className={`flex items-center justify-between gap-3 rounded-sm border px-3 py-2 transition-colors ${
            activeRepo === r.repo ? "border-add" : "border-line"
          }`}
        >
          <button
            type="button"
            onClick={() => onSelect(r.repo)}
            className={`focus-ring flex-1 truncate text-left font-mono text-xs ${
              activeRepo === r.repo ? "text-add" : "text-fg hover:text-add"
            }`}
            title={r.repo}
          >
            {r.repo}
            <span className="ml-2 text-muted">{r.chunksIndexed} chunks</span>
          </button>
          <button
            type="button"
            onClick={() => onDelete(r.repo)}
            className="focus-ring rounded-sm px-2 py-1 font-mono text-xs text-remove hover:opacity-80"
            aria-label={`Delete ${r.repo}`}
          >
            delete
          </button>
        </div>
      ))}
    </div>
  );
}
