"use client";

// New: /ingest now accepts an optional repo_name alongside source (a
// GitHub URL or, for local runs, a filesystem path) — pass it to give the
// repo a friendly name to filter/delete by later instead of whatever name
// the backend derives automatically.

import { useState } from "react";

export default function RepoInput({
  onSubmit,
  disabled,
}: {
  onSubmit: (source: string, repoName?: string) => void;
  disabled?: boolean;
}) {
  const [source, setSource] = useState("");
  const [repoName, setRepoName] = useState("");

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (source.trim()) onSubmit(source.trim(), repoName.trim() || undefined);
      }}
      className="flex flex-col gap-3"
    >
      <div className="flex flex-col gap-3 sm:flex-row">
        <input
          type="text"
          value={source}
          onChange={(e) => setSource(e.target.value)}
          placeholder="https://github.com/owner/repo"
          disabled={disabled}
          className="focus-ring flex-1 rounded-sm border border-line bg-surface px-4 py-3 font-mono text-sm text-fg placeholder:text-muted"
        />
        <button
          type="submit"
          disabled={disabled || !source.trim()}
          className="focus-ring rounded-sm bg-add px-6 py-3 text-sm font-medium text-ink transition-opacity hover:opacity-90 disabled:opacity-40"
        >
          Load repo
        </button>
      </div>
      <input
        type="text"
        value={repoName}
        onChange={(e) => setRepoName(e.target.value)}
        placeholder="Optional name for this repo (defaults to owner/repo)"
        disabled={disabled}
        className="focus-ring rounded-sm border border-line bg-surface px-4 py-2.5 font-mono text-xs text-fg placeholder:text-muted"
      />
    </form>
  );
}
